-- ----------------------------------------------------------------
-- Creatures show what the 15595 client was sent: the fields of the creature
-- query reply take the values of retail 15595 sniffs.
--
-- Name, subname, cursor icon, type, family, type flags, rank, kill credit and
-- models come from the Cataclysm Preservation Project's world database (rows
-- verified on build 15595). Its values agree with retail client caches of
-- builds 13623 and 14480 on 99.3 to 100 per cent of these fields. A text the
-- sniff leaves empty stays when a retail cache holds our text (the Arcane
-- Reforgers' subname). Quest items come from the newest retail cache that
-- holds the creature.
--
-- Entries 3 to 660 held their creature type in the family column; they now
-- carry the type and family the client has. Model 36452, which 229 now uses,
-- gets its `creature_model_info` row.
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '11';
    SET @cOldContent = '003';

    SET @cNewVersion = '22';
    SET @cNewStructure = '11';
    SET @cNewContent = '004';
    SET @cNewDescription = 'Creature_Query_Values';
    SET @cNewComment = 'Creatures take the query-reply values of the retail 15595 sniffs';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
